     if 0<=nx<R and 0<=ny<C and base[nx][ny]==2 and (nx,ny) not in seen:
      seen.add((nx,ny)); q.append((nx,ny))
   comps.append(comp)
[(len(x), min(r for r,c in x), max(r for r,c in x), min(c for r,c in x), max(c for r,c in x), any(c==5 for r,c in x)) for x in comps]

